import re

"""Deterministic AST & Rule-based linter engine for SQL, Python, and Shell."""

from dataclasses import asdict, dataclass
from typing import Any

try:
    import sqlglot
    from sqlglot.tokens import TokenType as _SgTokenType

    _HAS_SQLGLOT = True
except Exception:
    _HAS_SQLGLOT = False


@dataclass
class ProposedFix:
    """Represents a single proposed change generated by the linter."""

    fix_id: str
    file_path: str
    line_number: int
    category: str
    severity: str
    description: str
    original_code: str
    proposed_code: str
    rule_reference: str

    def to_dict(self) -> dict[str, Any]:
        """Convert dataclass instance to dict."""
        return asdict(self)


def split_sql_statements(content: str) -> list[str]:
    """Split SQL into statements on top-level semicolons."""
    if _HAS_SQLGLOT and content:
        try:
            parts, start = [], 0
            for tok in sqlglot.tokenize(content):
                if tok.token_type == _SgTokenType.SEMICOLON:
                    parts.append(content[start : tok.start])
                    start = tok.end + 1
            parts.append(content[start:])
            return [p.strip() for p in parts if p.strip()]
        except Exception:  # noqa: S110
            pass
    return [p.strip() for p in content.split(";") if p.strip()]


def quick_validate_sql_syntax(
    sql: str, template_vars: dict[str, str] | None = None
) -> str:
    """Fast syntax pre-check using sqlglot without BigQuery network trip."""
    if not (_HAS_SQLGLOT and sql and sql.strip()):
        return ""
    probe = sql
    for k, v in (template_vars or {}).items():
        probe = probe.replace("${" + k + "}", str(v))
    # Skip only genuine <placeholder_name> templates — comparison
    # operators (a < b AND c > d) must still get a syntax check.
    if "${" in probe or re.search(r"<[A-Za-z_][A-Za-z0-9_]*>", probe):
        return ""
    try:
        sqlglot.parse(probe, read="bigquery")
        return ""
    except Exception as e:
        return str(e).splitlines()[0] if str(e) else "Syntax error"


def lint_sql_content(
    content: str,
    file_path: str = "query.sql",
    dataset_param_map: dict[str, str] | None = None,
) -> list[ProposedFix]:
    """Generate structured fix proposals for a SQL file."""
    fixes: list[ProposedFix] = []
    lines = content.splitlines()
    fix_counter = 1

    # 1. Check for dataset hardcoding
    if dataset_param_map:
        for line_idx, line in enumerate(lines, start=1):
            for real_ds, var_ref in dataset_param_map.items():
                if real_ds in line and var_ref not in line:
                    new_line = line.replace(real_ds, var_ref)
                    fixes.append(
                        ProposedFix(
                            fix_id=f"fix-sql-{fix_counter}",
                            file_path=file_path,
                            line_number=line_idx,
                            category="compliance",
                            severity="info",
                            description=(
                                f"Parameterize dataset '{real_ds}' -> '{var_ref}'."
                            ),
                            original_code=line,
                            proposed_code=new_line,
                            rule_reference="sql-dataset-parameterization",
                        )
                    )
                    fix_counter += 1

    # 2. Check for DELETE/UPDATE without WHERE clause
    upper_content = content.upper()
    if "DELETE FROM" in upper_content or re.search(r"\bUPDATE\b", upper_content):
        for stmt in split_sql_statements(content):
            # Comments must not satisfy the WHERE requirement, and
            # LAST_UPDATE-style identifiers must not trigger the rule.
            code_only = re.sub(r"--[^\n]*|/\*.*?\*/", "", stmt, flags=re.S)
            stmt_upper = code_only.upper()
            is_mod = bool(
                re.search(r"\bDELETE\s+FROM\b", stmt_upper)
                or re.search(r"\bUPDATE\b", stmt_upper)
            )
            if is_mod and not re.search(r"\bWHERE\b", stmt_upper):
                first_word = (
                    "DELETE" if re.search(r"\bDELETE\s+FROM\b", stmt_upper) else "UPDATE"
                )
                line_no = 1
                keyword_re = re.compile(rf"\b{first_word}\b")
                for idx, line_str in enumerate(lines, start=1):
                    if keyword_re.search(line_str.upper()):
                        line_no = idx
                        break
                fixes.append(
                    ProposedFix(
                        fix_id=f"fix-sql-{fix_counter}",
                        file_path=file_path,
                        line_number=line_no,
                        category="security",
                        severity="critical",
                        description=(
                            "Missing WHERE clause on UPDATE/DELETE statement."
                        ),
                        original_code=stmt,
                        proposed_code=f"{stmt}\nWHERE <MISSING_FILTER_REQUIRED>;",
                        rule_reference="sql-missing-filter",
                    )
                )
                fix_counter += 1

    # 3. Check for Cartesian JOINs
    for line_idx, line in enumerate(lines, start=1):
        line_u = line.upper()
        if (
            " JOIN " in line_u
            and "CROSS JOIN" not in line_u
            and " ON " not in line_u
            and " USING " not in line_u
        ):
            fixes.append(
                ProposedFix(
                    fix_id=f"fix-sql-{fix_counter}",
                    file_path=file_path,
                    line_number=line_idx,
                    category="optimization",
                    severity="warning",
                    description=(
                        "JOIN missing ON/USING clause is a Cartesian product risk."
                    ),
                    original_code=line,
                    proposed_code=f"{line.rstrip()} ON <JOIN_CONDITION_REQUIRED>",
                    rule_reference="sql-missing-join-condition",
                )
            )
            fix_counter += 1

    # 4. Check for unpartitioned window functions
    for line_idx, line in enumerate(lines, start=1):
        u = line.upper()
        if "OVER" in u and "ORDER BY" in u and "PARTITION BY" not in u:
            fixes.append(
                ProposedFix(
                    fix_id=f"fix-sql-{fix_counter}",
                    file_path=file_path,
                    line_number=line_idx,
                    category="optimization",
                    severity="warning",
                    description=(
                        "Window OVER(ORDER BY) with no PARTITION BY scans table."
                    ),
                    original_code=line,
                    proposed_code=line.replace("OVER (", "OVER (PARTITION BY <KEY> "),
                    rule_reference="sql-unpartitioned-window",
                )
            )
            fix_counter += 1

    return fixes


def lint_python_dag_content(
    content: str,
    file_path: str = "dag.py",
) -> list[ProposedFix]:
    """Generate structured fix proposals for Python Airflow DAG files."""
    fixes: list[ProposedFix] = []
    lines = content.splitlines()
    fix_counter = 1

    if "DAG(" in content and "catchup=" not in content:
        for line_idx, line in enumerate(lines, start=1):
            if "DAG(" in line:
                indent = " " * (len(line) - len(line.lstrip()))
                new_line = f"{line}\n{indent}    catchup=False,"
                fixes.append(
                    ProposedFix(
                        fix_id=f"fix-py-{fix_counter}",
                        file_path=file_path,
                        line_number=line_idx,
                        category="compliance",
                        severity="warning",
                        description="Missing 'catchup=False' in DAG definition.",
                        original_code=line,
                        proposed_code=new_line,
                        rule_reference="airflow-dag-catchup",
                    )
                )
                fix_counter += 1
                break

    if "timedelta" in content and "import timedelta" not in content:
        for line_idx, line in enumerate(lines, start=1):
            if "from datetime import datetime" in line and "timedelta" not in line:
                new_line = line.replace("import datetime", "import datetime, timedelta")
                fixes.append(
                    ProposedFix(
                        fix_id=f"fix-py-{fix_counter}",
                        file_path=file_path,
                        line_number=line_idx,
                        category="syntax",
                        severity="warning",
                        description="Import 'timedelta' from datetime module.",
                        original_code=line,
                        proposed_code=new_line,
                        rule_reference="python-missing-import",
                    )
                )
                fix_counter += 1
                break

    return fixes
